/// Compare two rows of sort-prefix columns using the collation from the sort description when present.
/// Without this, values that are equal under the ORDER BY collation (for example 'a' and 'A' under a
/// case-insensitive collation) would be treated as distinct sorting prefixes and filled separately.
static int compareSortPrefixAt(
    const IColumn & lhs, size_t lhs_row, const IColumn & rhs, size_t rhs_row, const SortColumnDescription & desc)
{
    if (desc.collator && lhs.isCollationSupported())
        return lhs.compareAtWithCollation(lhs_row, rhs_row, rhs, desc.nulls_direction, *desc.collator);

    return lhs.compareAt(lhs_row, rhs_row, rhs, desc.nulls_direction);
}

